down_revision: str | None = "6976918846d4"
branch_labels: str | Sequence[str] | None = None
depends_on: str | Sequence[str] | None = None


def upgrade() -> None:
    bind = op.get_bind()
    bind.exec_driver_sql("PRAGMA foreign_keys=OFF")
    try:
        # 1. The new columns, with defaults so existing rows are valid.
        with op.batch_alter_table("device", schema=None) as batch_op:
            batch_op.add_column(
                sa.Column(
                    "quiet_hours",
                    sa.Boolean(),
                    nullable=False,
                    server_default=sa.false(),
                )
            )
            batch_op.add_column(sa.Column("quiet_from", sa.Time(), nullable=True))
            batch_op.add_column(sa.Column("quiet_to", sa.Time(), nullable=True))

        # 2. Carry the window over. Only the window: the brightness, the saved
        #    settings and the active flag have nowhere to go, which is the
        #    point of the change.
        bind.exec_driver_sql(
            "UPDATE device SET quiet_hours = night_mode,"
            " quiet_from = night_from, quiet_to = night_to"
        )

        # 3. Only now drop the old ones.
        with op.batch_alter_table("device", schema=None) as batch_op:
            for column in (
                "night_mode",
                "night_from",
                "night_to",
                "night_brightness",
                "night_active",
                "night_saved",
            ):
                batch_op.drop_column(column)
    finally:
        bind.exec_driver_sql("PRAGMA foreign_keys=ON")


